return items.map(item => {
  const d = item.json || {};
  const ts = Date.now();
  const encontrado = Number(d.estudiante_encontrado || 0) === 1;

  const codigo = encontrado
    ? String(d.codigo_estudiante_bd || '').trim()
    : 'EST-' + ts;

  const nombre = encontrado
    ? String(d.nombre_estudiante_bd || '').trim()
    : String(d.nombres_form || '').trim();

  const programa = encontrado
    ? String(d.programa_academico_bd || '').trim()
    : String(d.programa_form || '').trim();

  item.json.estudiante_encontrado = encontrado;
  item.json.estudiante_nuevo = !encontrado;
  item.json.codigo_estudiante = codigo;
  item.json.nombre_estudiante = nombre;
  item.json.programa_academico = programa;

  return item;
});

return items.map(item => {
  const d = item.json || {};

  const dni = String(d.dni || '').trim();
  const correo = String(d.correo || '').trim().toLowerCase();
  const nombre = String(d.nombre_estudiante || '').trim();
  const programa = String(d.programa_academico || '').trim();
  const periodo = String(d.periodo_academico || '').trim();
  const curso = String(d.curso || '').trim();

  const dniValido = /^\d{8}$/.test(dni);
  const correoValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(correo);
  const origenValido = d.origen_solicitud === 'formulario_cefic';

  const camposCompletos = Boolean(
    dni && correo && nombre && programa && periodo && curso
  );

  const longitudesValidas =
    nombre.length <= 150 &&
    programa.length <= 150 &&
    periodo.length <= 50 &&
    curso.length <= 150 &&
    correo.length <= 150;

  d.dni_valido = dniValido;
  d.correo_valido = correoValido;
  d.origen_valido = origenValido;
  d.campos_validos = camposCompletos;
  d.longitudes_validas = longitudesValidas;
  d.entrada_valida = dniValido && correoValido && origenValido && camposCompletos && longitudesValidas;

  d.control_validacion_origen = true;
  d.control_validacion_entrada = true;

  return item;
});

return items.map(item => {
  const d = item.json || {};

  const texto = [
    d.dni,
    d.correo,
    d.nombre_estudiante,
    d.programa_academico,
    d.periodo_academico,
    d.curso
  ].join(' ').toLowerCase();

  const firmas = [
    { nombre: 'script_html', regex: /<\s*script|javascript\s*:/i },
    { nombre: 'sql_union', regex: /\bunion\s+select\b/i },
    { nombre: 'sql_drop', regex: /\bdrop\s+table\b/i },
    { nombre: 'sql_tautologia', regex: /(['"]?\s*or\s+['"]?1['"]?\s*=\s*['"]?1)/i },
    { nombre: 'comentario_sql', regex: /(--|\/\*|#)/ },
    { nombre: 'path_traversal', regex: /(\.\.\/|\.\.\\)/ }
  ];

  const coincidencias = firmas
    .filter(f => f.regex.test(texto))
    .map(f => f.nombre);

  d.patrones_sospechosos = coincidencias;
  d.contenido_sospechoso = coincidencias.length > 0;
  d.control_filtrado = true;

  return item;
});

return items.map(item => {
  const d = item.json || {};

  d.prompt_groq = `Actúa como analista de ciberseguridad para CEFIC-Perú.

Evalúa una solicitud de matrícula recibida mediante formulario web.

Clasifica únicamente como:
- legitimo
- registro_anomalo

Asigna un score de riesgo entero entre 1 y 10.

IMPORTANTE:
- Un correo externo no es sospechoso por sí solo.
- Un estudiante nuevo tampoco es sospechoso por sí solo.
- Considera validaciones de formato, campos incompletos y patrones de entrada sospechosos.
- No evalúes si académicamente merece la matrícula; solo riesgo de seguridad.

Responde EXCLUSIVAMENTE con JSON válido:
{"categoria":"legitimo|registro_anomalo","score":1,"justificacion":"texto breve"}

Estudiante encontrado: ${d.estudiante_encontrado}
Estudiante nuevo: ${d.estudiante_nuevo}
DNI válido: ${d.dni_valido}
Correo válido: ${d.correo_valido}
Entrada válida: ${d.entrada_valida}
Código: ${d.codigo_estudiante}
Nombre: ${d.nombre_estudiante}
Programa: ${d.programa_academico}
Periodo: ${d.periodo_academico}
Curso: ${d.curso}
Patrones sospechosos: ${JSON.stringify(d.patrones_sospechosos)}`;

  return item;
});

